<template><section class="booking"><button class="back" @click="$router.push(route.query.from==='personal' ? '/personal' : '/doctors')">← 返回{{route.query.from==='personal'?'个人中心':'医生列表'}}</button><h1>医生预约与排号</h1><p>请选择医生和日期。当前排班为项目内配置，实际出诊以机构确认为准。</p><div class="booking-grid"><article><h2>预约医生</h2><label>选择医生<select v-model="profileId" @change="loadCalendar"><option v-for="d in doctors" :key="d.id" :value="d.id">{{d.name}}</option></select></label><div v-if="loading">正在加载排班…</div><div v-else class="date-list"><button v-for="day in days" :key="day.date" :class="{chosen:date===day.date}" :disabled="day.remaining===0" @click="date=day.date">{{day.date}}<small>{{day.remaining?'剩余 '+day.remaining+' 个名额':'已满'}}</small></button></div><button class="primary" :disabled="!date||busy" @click="book">{{busy?'提交中…':'确认预约'}}</button></article><article><h2>我的医生预约</h2><p v-if="!appointments.length">暂无预约记录</p><div v-for="item in appointments" :key="item.appointmentId" class="record"><strong>{{doctorName(item.profileId)}} · {{format(item.appointmentDate)}}</strong><p>排队号 {{item.queueNo}} · {{item.state==='BOOKED'?'已预约':'已取消'}}</p><button v-if="item.state==='BOOKED' && format(item.appointmentDate)>=today" class="outline" :disabled="busy" @click="cancel(item)">取消预约</button></div></article></div><p v-if="error" class="failure" role="alert">{{error}}</p><p v-if="notice" class="success" role="status">{{notice}}</p></section></template>
<script setup>
import {ref,onMounted} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import axios from 'axios'
const doctors=ref([])
const route=useRoute(),router=useRouter(),profileId=ref(''),date=ref(''),days=ref([]),appointments=ref([]),error=ref(''),notice=ref(''),busy=ref(false),loading=ref(false)
const today=new Date().toLocaleDateString('en-CA'),api=axios.create({baseURL:'/tijian',timeout:10000})
const format=s=>String(s||'').slice(0,10),doctorName=id=>doctors.value.find(d=>d.id===id)?.name||id
async function call(path,data={}){try{return (await api.post('/doctorAppointments/'+path,data)).data}catch(e){if(e.response?.status===401){sessionStorage.removeItem('tijianUser');router.replace('/login')}throw e}}
async function loadCalendar(){date.value='';loading.value=true;try{days.value=await call('calendar',{profileId:profileId.value})}catch(e){error.value='排班加载失败，请检查服务。'}finally{loading.value=false}}
async function loadList(){appointments.value=await call('list')}
async function book(){if(!date.value||busy.value)return;busy.value=true;error.value='';notice.value='';const chosen=date.value;try{const r=await call('book',{profileId:profileId.value,date:chosen});notice.value=chosen+' 预约成功，排队号 '+r.queueNo+'。';await Promise.all([loadCalendar(),loadList()])}catch(e){error.value=e.response?.status===409?'该日期已预约或名额已满，请刷新后查看。':'预约未完成，请检查日期和服务。'}finally{busy.value=false}}
async function cancel(item){if(!window.confirm('确定取消该预约吗？'))return;busy.value=true;error.value='';try{await call('cancel',{appointmentId:item.appointmentId});notice.value='预约已取消。';await Promise.all([loadCalendar(),loadList()])}catch(e){error.value='取消未完成，请刷新后重试。'}finally{busy.value=false}}
onMounted(async()=>{try{doctors.value=await call('doctors');profileId.value=doctors.value.some(d=>d.id===route.query.id)?route.query.id:(doctors.value[0]?.id || '');await Promise.all([profileId.value?loadCalendar():Promise.resolve(),loadList()])}catch(e){error.value='预约记录加载失败。'}})
</script>
<style scoped>.booking>p{color:#718d84;line-height:1.7;margin:14px 0}.booking-grid{display:grid;grid-template-columns:1.4fr 1fr;gap:18px;margin-top:22px}.booking article{padding:24px;background:white;border:1px solid #e3eeeb;border-radius:14px}.booking h2{font-size:18px;margin-bottom:20px}.booking label{display:grid;gap:10px;font-size:14px}.booking select{padding:10px;border:1px solid #dce9e3;border-radius:8px;background:white}.date-list{display:grid;grid-template-columns:repeat(3,1fr);gap:8px;max-height:270px;overflow:auto;margin:18px 0}.date-list button{background:#f5faf7;border:1px solid #e3eeeb;border-radius:8px;padding:10px;color:#365c50}.date-list button.chosen{border-color:#138c75;background:#e0f5e9}.date-list small{display:block;margin-top:5px}.record{padding:15px 0;border-top:1px solid #edf3f0}.record p{margin:8px 0;color:#718d84}.failure{color:#b14b42!important}.success{color:#138c75!important}@media(max-width:700px){.booking-grid{grid-template-columns:1fr}.date-list{grid-template-columns:repeat(2,1fr)}}</style>